    ('fc029995-b6bb-4375-a5fa-9a0eb7d0fa85'::uuid, 'scope_reason', 'E3: period_start 655 is 155 years past the rest of world cutoff of 500 AD', 'D58 label rule (owner, 2026-10-24): rest of world, period_start 655 lies inside its window through 1500 AD; the E3 retirement no longer holds', 'scope-unretire-2026-10-24:fc029995-b6bb-4375-a5fa-9a0eb7d0fa85:scope_reason', 'scope-unretire-2026-10-24 (d58-label-rule): scope_reason ''E3: period_start 655 is 155 years past the rest of world cutoff of 500 AD'' -> ''D58 label rule (owner, 2026-10-24): rest of world, period_start 655 lies inside its window through 1500 AD; the E3 retirement no longer holds''', 'Sakafune-ishi Ruins | Monument | 34.47550241309402 | 135.82393001784092 | Japan | 655 | NULL | d27f4067a1f8d9b47cbf8b7833bd5395 | 4ce459b31668301e0f3f36a8cc5c4978', '[{"source": "remediation_change_log:42760", "url": "remediation_change_log", "quote": "2026-09-23_mechanical-scope-e4: scope_status None -> retired"}, {"source": "pipeline/normalizers/dates.py", "url": "scope_region", "quote": "rest of world"}]'::jsonb),
